import type { IndustryPack, PackField, ProductCapabilityRecommendation } from "../index.ts";

type PackDraft = Omit<IndustryPack, "version" | "defaultAutomations"> & {
  version?: string;
  defaultAutomations?: IndustryPack["defaultAutomations"];
};

const pack = (draft: PackDraft): IndustryPack => ({
  version: "1.0.0",
  defaultAutomations: [],
  ...draft,
});

const field = (key: string, label: string, type: PackField["type"], options?: readonly string[], extra: Omit<PackField, "key" | "label" | "type" | "options"> = {}): PackField => ({
  key, label, type, ...(options ? { options } : {}), ...extra,
});
const rec = (featureKey: string, recommendation: ProductCapabilityRecommendation["recommendation"], rationale: string, rules?: ProductCapabilityRecommendation["rules"]): ProductCapabilityRecommendation => ({ featureKey, recommendation, rationale, ...(rules ? { rules } : {}) });
const question = (key: string, prompt: string, answerType: "boolean" | "number" | "enum" = "boolean", options?: readonly string[]) => ({ key, prompt, answerType, ...(options ? { options } : {}) });
const dateWebsite = (headline: string, description: string, signupSteps: readonly string[], sections: readonly string[] = ["hero", "services", "how_it_works", "faq", "quote_request", "contact"]): IndustryPack["website"] => ({
  template: "fresh", sections, signupSteps, heroHeadline: headline, heroDescription: description,
});

